import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzCascaderModule, NzCascaderOption } from 'ng-zorro-antd/cascader';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-cascader — CVA (mảng value phân cấp), bọc nz-cascader. HRM: org/địa danh. */
@Component({
  selector: 'hrm-cascader',
  imports: [FormsModule, NzCascaderModule],
  template: `
    <nz-cascader
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      (nzClear)="markTouched()"
      [nzOptions]="options()"
      [nzPlaceHolder]="placeholder()"
      [nzAllowClear]="allowClear()"
      [nzShowSearch]="showSearch()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"></nz-cascader>
  `,
  host: { class: 'hrm-cascader', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmCascader), multi: true }],
})
export class HrmCascader extends HrmControl<(string | number)[]> {
  readonly options = input<NzCascaderOption[]>([]);
  readonly placeholder = input('');
  readonly allowClear = input(true);
  readonly showSearch = input(false);
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
}
